import {T,step,v,n,o,p,f,pow,sub,prime,eq,plus,minus,x,y,C,fn,exp,integral,dx,dy,abs,lines,r} from '../../../study/math.js';
const vv=v('v'),A=v('A'),X=v('X'),Y=v('Y');
const zero=n(0),one=n(1),two=n(2),three=n(3);
const dv=v('d')+vv,dX=v('d')+X,dY=v('d')+Y;
const x0=sub(x,zero),y0=sub(y,zero);
const sqrt=s=>'<msqrt>'+r(s)+'</msqrt>';
const x2=pow(x,two),y2=pow(y,two),v2=pow(vv,two),X2=pow(X,two),Y2=pow(Y,two);
export const transformationFamilies={
 circle:{
  name:'y′ = (y²−x²)/(2xy)',constantLabel:'A',
  separated:f(two+vv,v2+plus+one)+dv+eq+minus+f(dx,x),
  solution:x2+plus+y2+eq+A+x,
  excluded:T('x=0 ve y=0 orijinal denklemde tanımsızdır. y(0)=0 bu aileyi seçemez; y=0 sabit bir çözüm değildir.','x=0 and y=0 are undefined in the original equation. The datum y(0)=0 cannot select this family; y=0 is not a constant solution.'),
  interpretation:T('Başlangıç verisi A=(x₀²+y₀²)/x₀ değerini belirler; eğri x²+y²=Ax dairesidir. Merkez (A/2,0), yarıçap A/2’dir. Bağlı aralık (0,A) olur; x=0 ve y=0 sınırları orijinal denklemde dışlanır.','The initial datum fixes A=(x₀²+y₀²)/x₀ and the curve is the circle x²+y²=Ax. Its centre is (A/2,0) and its radius is A/2. The connected interval is (0,A); the boundaries x=0 and y=0 are excluded by the original equation.'),
  controlsNote:T('A ve B farklı çaplı iki daire seçer. y(1)=0 denemesi geçersizdir; sıfır bu ailenin başlangıç verisi olamaz.','A and B select circles of different diameters. y(1)=0 is invalid; zero cannot be initial data for this family.')
 },
 ellipse:{
  name:'y′ = (2x−y)/(x−2y)',constantLabel:'A',
  separated:f(one+minus+two+vv,v2+minus+vv+plus+one)+dv+eq+two+f(dx,x),
  solution:x2+minus+x+y+plus+y2+eq+A,
  excluded:T('x−2y=0 orijinal paydayı sıfırlar. A=0 durumu noktaya çöker; seçilen dalda x−2y≠0 korunur.','x−2y=0 makes the original denominator vanish. A=0 collapses to a point; the selected branch keeps x−2y≠0.'),
  interpretation:T('A büyüdükçe x²−xy+y²=A elipsi büyür. İki uçta x−2y=0 olur; bağlı aralık bu iki kutup arasındadır.','As A grows, the ellipse x²−xy+y²=A grows. At both ends x−2y=0; the connected interval lies between these two poles.'),
  controlsNote:T('A/B farklı elipsler seçer. y(1)=0,5 seçilirse 2y−x=0 olur ve başlangıç noktası paydayı sıfırlar; geçersizdir.','A/B select different ellipses. Choosing y(1)=0.5 makes 2y−x=0 and the initial point hits the denominator; it is invalid.')
 },
 sum:{
  name:'y′ = (x+y)²',constantLabel:'C',
  separated:f(dv,one+plus+v2)+eq+dx,
  solution:y+eq+fn('tan',x+plus+C)+minus+x,
  excluded:T('1+v² hiç sıfır olmaz; kayıp sabit dal yoktur. Çözümün kutupları cos(x+C)=0 noktalarıdır.','1+v² never vanishes, so no constant branch is lost. The solution poles are the points where cos(x+C)=0.'),
  interpretation:T('C başlangıç noktasını kaydırır. Her dal iki dikey kutup arasında yaşar; kutuplar geçilmez ve aralık açık yazılır.','C shifts the initial point. Each branch lives between two vertical poles; poles are never crossed and the interval is written open.'),
  controlsNote:T('A/B aynı tanjant ailesinin farklı dallarını seçebilir. Grafikteki dikey sınırlar gerçek kutuplardır.','A/B can select different branches of the same tangent family. The vertical boundaries in the plot are genuine poles.')
 },
 radical:{
  name:'y′ = (x−√(x²−y²))/y',constantLabel:'C',
  separated:dv+eq+dx,
  solution:x2+minus+y2+eq+pow(x+plus+C,two),
  excluded:T('y=0 ve v=0 dışlanır. Orijinal ifade x>0 ve |y|<x ister; seçilen dalda x>−C ve y≠0 korunur.','y=0 and v=0 are excluded. The original expression requires x>0 and |y|<x; the selected branch keeps x>−C and y≠0.'),
  interpretation:T('C negatiftir; x²−y²=(x+C)² parabol ailesini verir. Bağlı aralık (−C,∞) olur ve x=−C sınırında v=0’a yaklaşılır.','C is negative; x²−y²=(x+C)² gives a parabolic family. The connected interval is (−C,∞), approaching v=0 at the boundary x=−C.'),
  controlsNote:T('A/B için |y(1)|<1 gerekir. y=0 seçimi geçersizdir; v²=x²−y² dönüşümü sıfırda çözülmez.','A/B require |y(1)|<1. Choosing y=0 is invalid because the transformation v²=x²−y² degenerates at zero.')
 }
};
const homogeneous=[
 step('1. Homojen biçimi tanı','1. Recognize the homogeneous form',lines(prime('y')+plus+f(x,y)+plus+two+eq+zero,prime('y')+eq+minus+p(f(one,vv)+plus+two),v('f')+p(vv)+minus+vv+eq+minus+f(pow(vv+plus+one,two),vv)),'Denklem homojendir: sağ taraf yalnız v=y/x’e bağlıdır. f(v)−v=−(v+1)²/v. v=−1 kökü y=−x dalını verir; bu dal y(0)=1’i sağlamaz ama denklemin gerçek bir çözümüdür.','The equation is homogeneous: the right side depends only on v=y/x. Here f(v)−v=−(v+1)²/v. The root v=−1 gives the branch y=−x; it does not satisfy y(0)=1, but it is a genuine solution of the ODE.'),
 step('2. Dönüşümü uygula','2. Apply the transformation',lines(y+eq+vv+x,prime('y')+eq+vv+plus+x+prime('v'),vv+plus+x+prime('v')+eq+minus+f(one+plus+two+vv,vv),x+prime('v')+eq+minus+f(pow(vv+plus+one,two),vv)),'y=vx çarpım kuralıyla y′=v+xv′. 1/v+2 ortak paydada (1+2v)/v olur; v’yi çıkarınca xv′=−(v+1)²/v kalır. v=−1 dalını ayırıyoruz; bölme onu silebilir.','The product rule for y=vx gives y′=v+xv′. The term 1/v+2 becomes (1+2v)/v over a common denominator; subtracting v leaves xv′=−(v+1)²/v. We separate the branch v=−1 because division can discard it.'),
 step('3. Ayır ve integre et','3. Separate and integrate',lines(f(vv,pow(vv+plus+one,two))+dv+eq+minus+f(dx,x),fn('ln',abs(vv+plus+one))+plus+f(one,vv+plus+one)+eq+minus+fn('ln',abs(x))+plus+C),'v/(v+1)²=1/(v+1)−1/(v+1)². İntegral ln|v+1|+1/(v+1) olur; sağda −ln|x| vardır. x≠0 ve v≠−1 bölgesindeyiz.','Since v/(v+1)²=1/(v+1)−1/(v+1)², the integral is ln|v+1|+1/(v+1); the right side is −ln|x|. Work on x≠0 and v≠−1.'),
 step('4. Geri dön ve veriyi uygula','4. Back-substitute and apply the datum',lines(fn('ln',abs(y+plus+x))+plus+f(x,y+plus+x)+eq+C,fn('ln',one)+plus+zero+eq+C+o('⇒')+C+eq+zero,fn('ln',y+plus+x)+plus+f(x,y+plus+x)+eq+zero),'v=y/x geri konur ve logaritmalar birleştirilir: ln|y+x|+x/(y+x)=C. y(0)=1 için ln1+0=C, yani C=0. Başlangıç noktası y+x>0 dalındadır.','Put back v=y/x and combine logarithms: ln|y+x|+x/(y+x)=C. For y(0)=1, ln1+0=C, so C=0. The initial point lies on the branch y+x>0.'),
 step('5. Doğrula ve aralığı yaz','5. Verify and state the interval',lines(f(v('d'),v('d')+x)+p(fn('ln',y+plus+x)+plus+f(x,y+plus+x))+eq+zero+o('⇒')+prime('y')+plus+f(x,y)+plus+two+eq+zero,x+eq+minus+v('u')+fn('ln',v('u'))+o(',')+y+eq+v('u')+p(one+plus+fn('ln',v('u')))+o(',')+v('u')+o('>')+f(one,v('e'))+o('⇒')+x+o('&lt;')+f(one,v('e'))+o(',')+y+o('>')+zero),'Örtük türev y′=−(x+2y)/y, yani y′+x/y+2=0 verir. u=y+x ile x=−u ln u, y=u(1+ln u). (0,1) dalı u>1/e’ye karşılık gelir; x→1/e− iken y→0+, x→−∞ iken y→∞. En geniş aralık x<1/e, y>0; x=1/e’de y=0 olduğundan orijinal denklem tanımsızdır.','Implicit differentiation gives y′=−(x+2y)/y, hence y′+x/y+2=0. With u=y+x, x=−u ln u and y=u(1+ln u). The branch through (0,1) corresponds to u>1/e; as x→1/e−, y→0+, and as x→−∞, y→∞. The maximal interval is x<1/e with y>0; at x=1/e, y=0 and the original equation is undefined.')
];
const special=[
 step('1. Özel terimi bul','1. Spot the special term',prime('y')+eq+pow(p(x+plus+y),two),'Denklem ne ayrılabilir ne de y/x’in tek başına fonksiyonudur. Tekrarlanan özel terim x+y’dir; v=x+y seç.','The equation is neither separable nor a function of y/x alone. The repeated special term is x+y; choose v=x+y.'),
 step('2. İndirgenmiş denklemi kur','2. Build the reduced equation',lines(vv+eq+x+plus+y,prime('v')+eq+one+plus+prime('y'),prime('v')+eq+one+plus+v2),'v=x+y ise v′=1+y′. Orijinal denklemde y′=v² olduğundan v′=1+v² elde edilir.','If v=x+y, then v′=1+y′. Since the original equation gives y′=v², we obtain v′=1+v².'),
 step('3. Ayır ve integre et','3. Separate and integrate',lines(f(dv,one+plus+v2)+eq+dx,fn('arctan',vv)+eq+x+plus+C),'1+v² pozitiftir; bölme sabit bir dal kaybettirmez. İntegral arktanjanttır.','1+v² is positive, so division loses no constant branch. The integral is arctangent.'),
 step('4. Geri dön','4. Back-substitute',y+eq+fn('tan',x+plus+C)+minus+x,'v=tan(x+C) ve v=x+y olduğundan y=tan(x+C)−x. C başlangıç verisinden seçilir.','Since v=tan(x+C) and v=x+y, y=tan(x+C)−x. The constant C is selected by the initial datum.'),
 step('5. Doğrula ve aralığı belirle','5. Verify and state the interval',lines(prime('y')+eq+pow(fn('sec',x+plus+C),two)+minus+one+eq+pow(p(x+plus+y),two),x+plus+C+o('∈')+p(minus+f(v('π'),two)+o(',')+f(v('π'),two))),'sec²−1=tan² olduğundan türev orijinal denklemi verir. Seçilen bağlı aralıkta kosinüs sıfırlanmaz; kutuplar x+C=π/2+kπ’dir.','Since sec²−1=tan², the derivative recovers the original equation. On the selected connected interval cosine does not vanish; poles occur at x+C=π/2+kπ.')
];
export const transformationStudy={title:T('Dönüşüm, denklemi çözülebilir bir forma taşır.','A transformation moves the equation into a solvable form.'),intro:T('Önce hangi dönüşümün uyduğunu tahmin et. Homojen örneği ve özel terim örneğini ara işlemleriyle türet; sonra dört ailede başlangıç verisini ve tanım aralığını karşılaştır.','Predict which transformation fits. Derive a homogeneous example and a special-term example with intermediate work, then compare initial data and intervals in four families.'),paths:[{title:T('Örnek 2.4 · Homojen IVP','Example 2.4 · Homogeneous IVP'),prompt:T('v=y/x dönüşümü neden denklemi ayırılabilir yapar?','Why does v=y/x make the equation separable?'),steps:homogeneous,reflection:T('y=0 sınırını veya x=1/e ucunu çözüm aralığına katabilir misin?','Can you include the boundary y=0 or the endpoint x=1/e in the solution interval?')},{title:T('Örnek 2.9 · Özel dönüşüm','Example 2.9 · Special transformation'),prompt:T('x+y tekrarını gördüğünde neden v=x+y denersin?','Why try v=x+y when you see the repeated term x+y?'),steps:special,reflection:T('Tanjant çözümünün kutuplarını neden açık aralıkla yazmalıyız?','Why must the tangent solution’s poles be written as open boundaries?')}],predictions:[
 {id:'product-rule',question:T('y=vx dönüşümünde y′ ne olur?','What is y′ under y=vx?'),context:T('v=y/x ve y=vx; v, x’e bağlıdır.','v=y/x and y=vx; v depends on x.'),choices:T(['v+xv′','v′','xv′'],['v+xv′','v′','xv′']),answer:0,reason:T('y=vx bir çarpımdır; çarpım kuralı y′=v+xv′ verir. Yalnız v′ yazmak v’nin sabit olduğunu varsayar.','y=vx is a product; the product rule gives y′=v+xv′. Writing only v′ assumes v is constant.'),math:prime('y')+eq+vv+plus+x+prime('v'),try:T('Aşağıdaki daire ailesinde v=y/x dönüşümünü izle.','Follow the v=y/x transformation in the circle family below.')},
 {id:'special-sum',question:T('v=x+y seçilirse y′ yerine ne yazılır?','If v=x+y, what replaces y′?'),context:T('v=x+y olduğundan v′=1+y′.','Since v=x+y, v′=1+y′.'),choices:T(['v′−1','v′+1','v′'],['v′−1','v′+1','v′']),answer:0,reason:T('v′=1+y′ eşitliğini y′ için çöz: y′=v′−1. İşareti ters çevirmek sık yapılan hatadır.','Solve v′=1+y′ for y′: y′=v′−1. Reversing the sign is a common error.'),math:prime('v')+eq+one+plus+prime('y'),try:T('Aşağıdaki toplam ailesinde v′−1 ifadesini denklemde yerine koy.','Substitute v′−1 into the equation in the sum family below.')}
]};
const example24=[
 step('1. Homojenliği göster (1 puan)','1. Show homogeneity (1 point)',lines(prime('y')+plus+f(x,y)+plus+two+eq+zero,prime('y')+eq+minus+p(f(one,vv)+plus+two),v('f')+p(vv)+minus+vv+eq+minus+f(pow(vv+plus+one,two),vv),vv+eq+minus+one+o('⇒')+y+eq+minus+x),'Sağ taraf −(1/v+2) biçimindedir; v=y/x seçilir. f(v)−v=−(v+1)²/v. v=−1 kökü y=−x dalını verir; bu dal y(0)=1’i sağlamaz ama denklemin çözümüdür.','The right side is −(1/v+2), so choose v=y/x. Here f(v)−v=−(v+1)²/v. The root v=−1 gives y=−x; it does not satisfy y(0)=1, but it solves the ODE.'),
 step('2. Dönüşümü uygula (1 puan)','2. Apply the transformation (1 point)',lines(y+eq+vv+x,prime('y')+eq+vv+plus+x+prime('v'),vv+plus+x+prime('v')+eq+minus+f(one+plus+two+vv,vv),x+prime('v')+eq+minus+f(pow(vv+plus+one,two),vv)),'Çarpım kuralı y′=v+xv′ verir. 1/v+2 ortak paydada toplanır; v’yi çıkarınca xv′=−(v+1)²/v kalır.','The product rule gives y′=v+xv′. Combine 1/v+2 over a common denominator; subtracting v leaves xv′=−(v+1)²/v.'),
 step('3. Ayır ve integre et (1 puan)','3. Separate and integrate (1 point)',lines(f(vv,pow(vv+plus+one,two))+dv+eq+minus+f(dx,x),fn('ln',abs(vv+plus+one))+plus+f(one,vv+plus+one)+eq+minus+fn('ln',abs(x))+plus+C),'v/(v+1)²=1/(v+1)−1/(v+1)². İntegral ln|v+1|+1/(v+1); sağda −ln|x|. x≠0 ve v≠−1 korunur.','Since v/(v+1)²=1/(v+1)−1/(v+1)², the integral is ln|v+1|+1/(v+1); the right side is −ln|x|. Keep x≠0 and v≠−1.'),
 step('4. Aile ve başlangıç verisi (1 puan)','4. Family and initial datum (1 point)',lines(fn('ln',abs(y+plus+x))+plus+f(x,y+plus+x)+eq+C,fn('ln',one)+plus+zero+eq+C+o('⇒')+C+eq+zero,fn('ln',y+plus+x)+plus+f(x,y+plus+x)+eq+zero),'Geri dönüş ve logaritma birleştirmesi ln|y+x|+x/(y+x)=C verir. y(0)=1 için C=0; dal y+x>0 üzerindedir.','Back-substitution and combining logarithms give ln|y+x|+x/(y+x)=C. The datum y(0)=1 gives C=0; the branch has y+x>0.'),
 step('5. Doğrulama ve aralık (1 puan)','5. Verification and interval (1 point)',lines(f(v('d'),v('d')+x)+p(fn('ln',y+plus+x)+plus+f(x,y+plus+x))+eq+zero+o('⇒')+prime('y')+plus+f(x,y)+plus+two+eq+zero,x+eq+minus+v('u')+fn('ln',v('u'))+o(',')+y+eq+v('u')+p(one+plus+fn('ln',v('u')))+o(',')+v('u')+o('>')+f(one,v('e'))+o('⇒')+x+o('&lt;')+f(one,v('e'))+o(',')+y+o('>')+zero),'Örtük türev y′=−(x+2y)/y verir; bu orijinal denklemdir. u=y+x ile x=−u ln u, y=u(1+ln u). (0,1) dalı u>1/e’dedir; en geniş aralık x<1/e, y>0. x=1/e’de y=0 olduğundan uç nokta dışlanır.','Implicit differentiation gives y′=−(x+2y)/y, which is the original equation. With u=y+x, x=−u ln u and y=u(1+ln u). The branch through (0,1) has u>1/e; the maximal interval is x<1/e with y>0. At x=1/e, y=0, so the endpoint is excluded.')
];
const example26=[
 step('1. Normal biçim ve homojenlik (1 puan)','1. Normal form and homogeneity (1 point)',lines(p(y+plus+x)+dy+plus+p(x+minus+y)+dx+eq+zero,prime('y')+eq+f(y+minus+x,y+plus+x)),'x≠0 bölgesinde pay ve payda x’e bölünür; sağ taraf y/x’in fonksiyonudur. v=y/x seçilir.','On x≠0 divide numerator and denominator by x; the right side is a function of y/x. Choose v=y/x.'),
 step('2. İndirgenmiş denklem (1 puan)','2. Reduced equation (1 point)',lines(prime('y')+eq+vv+plus+x+prime('v'),x+prime('v')+eq+minus+f(v2+plus+one,vv+plus+one)),'v+xv′=(v−1)/(v+1); v’yi çıkarınca xv′=−(v²+1)/(v+1).','v+xv′=(v−1)/(v+1); subtracting v gives xv′=−(v²+1)/(v+1).'),
 step('3. Ayır ve integre et (1 puan)','3. Separate and integrate (1 point)',lines(f(vv+plus+one,v2+plus+one)+dv+eq+minus+f(dx,x),f(one,two)+fn('ln',v2+plus+one)+plus+fn('arctan',vv)+eq+minus+fn('ln',abs(x))+plus+C),'(v+1)/(v²+1)=v/(v²+1)+1/(v²+1). İntegraller sırasıyla (1/2)ln(v²+1) ve arctan v’dir.','(v+1)/(v²+1)=v/(v²+1)+1/(v²+1). The integrals are (1/2)ln(v²+1) and arctan v.'),
 step('4. Geri dön ve sadeleştir (1 puan)','4. Back-substitute and simplify (1 point)',fn('ln',x2+plus+y2)+plus+two+fn('arctan',f(y,x))+eq+C,'İki tarafı 2 ile çarp ve ln|x|’yi birleştir: ln(x²+y²)+2 arctan(y/x)=C.','Multiply by 2 and combine ln|x|: ln(x²+y²)+2 arctan(y/x)=C.'),
 step('5. Doğrulama ve bölge (1 puan)','5. Verification and domain (1 point)',lines(f(two+x+minus+two+y+prime('y'),x2+plus+y2)+plus+f(two+p(x+prime('y')+minus+one),x+plus+y)+eq+zero),'Örtük türev orijinal diferansiyel formu verir. v²+1>0 olduğundan kayıp sabit dal yoktur; x≠0 ve seçilen arktanjant dalı korunur.','Implicit differentiation recovers the original differential form. Since v²+1>0, no constant branch is lost; keep x≠0 and the selected arctangent branch.')
];
const example27=[
 step('1. Kesişim noktasını bul (1 puan)','1. Find the intersection (1 point)',lines(two+x+minus+y+plus+one+eq+zero,x+minus+two+y+plus+one+eq+zero,x+eq+minus+f(one,three)+o(',')+y+eq+f(one,three)),'İki doğru (h,k)=(−1/3,1/3) noktasında kesişir. Sabit terimleri yok etmek için eksenleri bu noktaya taşı.','The two lines intersect at (h,k)=(−1/3,1/3). Shift the axes to this point to remove the constant terms.'),
 step('2. Kaydırılmış denklem (1 puan)','2. Shifted equation (1 point)',lines(x+eq+X+minus+f(one,three)+o(',')+y+eq+Y+plus+f(one,three),f(dY,dX)+eq+f(two+X+minus+Y,X+minus+two+Y)),'x=X−1/3 ve y=Y+1/3 yazınca pay 2X−Y, payda X−2Y olur; denklem homojendir.','Substituting x=X−1/3 and y=Y+1/3 gives numerator 2X−Y and denominator X−2Y; the equation is homogeneous.'),
 step('3. Homojen dönüşüm (1 puan)','3. Homogeneous transformation (1 point)',lines(f(dY,dX)+eq+vv+plus+X+prime('v'),X+prime('v')+eq+f(two+p(v2+minus+vv+plus+one),one+minus+two+vv)),'v=Y/X. v’yi çıkarınca Xv′=2(v²−v+1)/(1−2v).','v=Y/X. Subtracting v gives Xv′=2(v²−v+1)/(1−2v).'),
 step('4. Ayır ve integre et (1 puan)','4. Separate and integrate (1 point)',lines(f(one+minus+two+vv,v2+minus+vv+plus+one)+dv+eq+two+f(dX,X),X2+p(v2+minus+vv+plus+one)+eq+A),'Payda v²−v+1’in türevi 2v−1’dir; bu yüzden sol integral −ln(v²−v+1). Üstel alınca X²(v²−v+1)=A.','The derivative of v²−v+1 is 2v−1, so the left integral is −ln(v²−v+1). Exponentiation gives X²(v²−v+1)=A.'),
 step('5. Eski değişkenlere dön (1 puan)','5. Return to the original variables (1 point)',lines(pow(Y,two)+minus+X+Y+plus+X2+eq+A,x2+minus+x+y+plus+y2+plus+x+minus+y+plus+f(one,three)+eq+A),'Y=y−1/3 ve X=x+1/3 geri konur; açılım x²−xy+y²+x−y+1/3=A olur. Sonuç, kaydırılmış merkezli bir elipstir; A>0 için gerçek eğri verir.','Put back Y=y−1/3 and X=x+1/3; expansion gives x²−xy+y²+x−y+1/3=A. The result is an ellipse with a shifted centre; it gives a real curve for A>0.')
];
const example212=[
 step('1. Köklü ifadeyi sadeleştir (1 puan)','1. Simplify the radical expression (1 point)',prime('y')+eq+f(sqrt(x+plus+y)+minus+sqrt(x+minus+y),sqrt(x+plus+y)+plus+sqrt(x+minus+y)),'Pay ve paydayı eşlenikle çarp; pay x²−y², payda y olur. x>0 ve |y|<x bölgesindeyiz.','Multiply numerator and denominator by the conjugate; the numerator becomes x²−y² and the denominator y. Work on x>0 and |y|<x.'),
 step('2. Sadeleşmiş denklem (1 puan)','2. Simplified equation (1 point)',prime('y')+eq+f(x+minus+sqrt(x2+minus+y2),y),'Kareköklü terim x²−y²’dir. Şimdi özel terim x²−y²’yi tek bir v ile temsil etmek istiyoruz.','The radical term is x²−y². We now want to represent the special term x²−y² by a single v.'),
 step('3. v²=x²−y² dönüşümü (1 puan)','3. The transformation v²=x²−y² (1 point)',lines(v2+eq+x2+minus+y2,two+x+minus+two+y+prime('y')+eq+two+vv+prime('v'),prime('y')+eq+f(x+minus+vv+prime('v'),y)),'Her iki tarafın türevi alınır. v>0 dalında karekök v’dir; y′ yerine (x−vv′)/y yazılır.','Differentiate both sides. On the branch v>0 the square root is v; replace y′ by (x−vv′)/y.'),
 step('4. İndirgenmiş denklem (1 puan)','4. Reduced equation (1 point)',lines(vv+prime('v')+eq+vv,prime('v')+eq+one+o(',')+vv+eq+x+C),'İki ifade eşitlenince vv′=v olur. v≠0 kolunda v′=1; integre edince v=x+C.','Equating the two expressions gives vv′=v. On v≠0, v′=1; integration gives v=x+C.'),
 step('5. Geri dön, doğrula, aralık (1 puan)','5. Back-substitute, verify, interval (1 point)',lines(x2+minus+y2+eq+pow(x+plus+C,two),y2+eq+minus+two+C+x+minus+pow(C,two)),'v=x+C geri konur. y²=−2Cx−C² parabol ailesi; v>0 dalında x>−C ve |y|<x. y=0, C=0 üyesidir; y=±x ise v=0 sınırındaki tekil çözümlerdir. Türev v′=1’i geri verir.','Put back v=x+C. The parabolic family is y²=−2Cx−C²; on the v>0 branch x>−C and |y|<x. The solution y=0 is the C=0 member, while y=±x are singular solutions on the boundary v=0. Differentiation returns v′=1.')
];
